(function() {
  'use strict';

  // 状态管理
  const state = {
    activeTerm: null,
    arrayType: 'uca' // 'ula' or 'uca'
  };

  // DOM 元素缓存
  const elements = {
    formulaTerms: document.querySelectorAll('#formula-h .term'),
    legendItems: document.querySelectorAll('.legend-item'),
    arrayDemos: {
      ula: document.getElementById('demo-ula'),
      uca: document.getElementById('demo-uca')
    },
    sourceButtons: document.querySelectorAll('[data-source]')
  };

  // 初始化
  function init() {
    bindFormulaEvents();
    bindLegendEvents();
    bindSourceEvents();
    // 默认高亮 UCA 相关项
    highlightTerm('ar');
  }

  // 绑定公式项交互
  function bindFormulaEvents() {
    elements.formulaTerms.forEach(term => {
      term.addEventListener('mouseenter', () => {
        const target = term.dataset.highlight;
        highlightTerm(target);
        updateArrayVisual(target);
      });

      term.addEventListener('mouseleave', () => {
        // 鼠标离开公式时，保持当前 Legend 的高亮状态，不立即清除
        // 除非用户点击了其他地方
      });

      term.addEventListener('click', () => {
         // 点击锁定高亮
         const target = term.dataset.highlight;
         highlightTerm(target);
         updateArrayVisual(target);
      });
    });
  }

  // 绑定图例交互
  function bindLegendEvents() {
    elements.legendItems.forEach(item => {
      item.addEventListener('mouseenter', () => {
        const target = item.dataset.target;
        highlightTerm(target);
        updateArrayVisual(target);
      });

      item.addEventListener('mouseleave', () => {
        // 恢复默认或保持上次交互
      });
    });
  }

  // 绑定来源按钮 (仅做视觉反馈，实际跳转由内核处理)
  function bindSourceEvents() {
    elements.sourceButtons.forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        const sourceId = btn.dataset.source;
        // 内核会监听此事件或 data 属性进行跳转
        // 此处仅做视觉反馈
        btn.style.borderColor = 'var(--accent)';
        setTimeout(() => {
          btn.style.borderColor = '';
        }, 300);
      });
    });
  }

  // 高亮公式项
  function highlightTerm(target) {
    elements.formulaTerms.forEach(t => {
      if (t.dataset.highlight === target) {
        t.classList.add('highlighted');
      } else {
        t.classList.remove('highlighted');
      }
    });
    state.activeTerm = target;
  }

  // 更新阵列视觉 (ULA vs UCA)
  function updateArrayVisual(term) {
    // 如果是仰角相关 (ar, theta_el)，强调 UCA 的优势，ULA 显示盲区
    if (term === 'ar' || term === 'toa') {
      // ToA 也需要精确角度，但这里主要展示仰角差异
      // 当鼠标悬停在 ToA 时，我们展示 UCA 能提供的完整参数
      setArrayActive('uca');
    } else if (term === 'at') {
      // 发射端同样需要 2D-AoD
      setArrayActive('uca');
    } else {
      // 默认状态
      setArrayActive('uca');
    }
  }

  function setArrayActive(type) {
    if (type === 'ula') {
      elements.arrayDemos.ula.classList.add('active');
      elements.arrayDemos.uca.classList.remove('active');
    } else {
      elements.arrayDemos.uca.classList.add('active');
      elements.arrayDemos.ula.classList.remove('active');
    }
  }

  // 启动
  init();
})();
